import React, { useState } from "react";
import { Form, FormGroup, Label, Input } from "reactstrap";
import { Link, useNavigate } from "react-router-dom";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { userRegisterSchema } from "../Validations/UserRegisterSchema";
import "../Styles/UserRegister.css";

// You may reuse your existing MAJORS list/colors/fonts from the project
const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const navigate = useNavigate();

  // Local states (kept to match teacher’s pattern with onChange inside register)
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState("");

  // Hook form setup with yup
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(userRegisterSchema),
    mode: "onTouched",
  });

  // On submit: save to localStorage and navigate
  const onSubmit = (data) => {
    const payload = { ...data, role: "student" };
    localStorage.setItem("userData", JSON.stringify(payload));
    alert("Student Registered ✅");
    navigate("/user-profile");
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      <div className="reg-card">
        <p className="reg-sub">Please fill in your details to continue</p>

        <Form onSubmit={handleSubmit(onSubmit)}>
          {/* Full Name */}
          <FormGroup>
            <Label>Full Name</Label>
            <Input
              type="text"
              placeholder="Your name"
              {...register("fullName", {
                value: fullName,
                onChange: (e) => setFullName(e.target.value),
              })}
            />
            <p className="error">{errors.fullName?.message}</p>
          </FormGroup>

          {/* Email */}
          <FormGroup>
            <Label>Email</Label>
            <Input
              type="email"
              placeholder="you@example.com"
              {...register("email", {
                value: email,
                onChange: (e) => setEmail(e.target.value),
              })}
            />
            <p className="error">{errors.email?.message}</p>
          </FormGroup>

          {/* Password */}
          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              {...register("password", {
                value: password,
                onChange: (e) => setPassword(e.target.value),
              })}
            />
            <p className="error">{errors.password?.message}</p>
          </FormGroup>

          {/* Major */}
          <FormGroup>
            <Label>Major</Label>
            <Input
              type="select"
              {...register("major", {
                value: major,
                onChange: (e) => setMajor(e.target.value),
              })}
            >
              {MAJORS.map((m, i) => (
                <option key={i} value={m}>
                  {m === "" ? "Select your major" : m}
                </option>
              ))}
            </Input>
            <p className="error">{errors.major?.message}</p>
          </FormGroup>

          {/* Age */}
          <FormGroup>
            <Label>Age</Label>
            <Input
              type="number"
              min="17"
              max="45"
              {...register("age", {
                value: age,
                onChange: (e) => setAge(e.target.value),
              })}
            />
            <p className="error">{errors.age?.message}</p>
          </FormGroup>

          <button type="submit" className="reg-btn">
            Sign up
          </button>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/login" className="login-link">
              Log in now!
            </Link>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default UserRegister;
